1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="color-scheme" content="light dark">
7	  <title>Animated Circle - Interactive Demo</title>
8	  <meta name="description" content="A responsive, accessible circle that changes color when clicked">
9	  <meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
10	  <meta name="theme-color" content="#111111" media="(prefers-color-scheme: dark)">
11	  <link rel="icon" href="data:,">
12	  <style>
13	    *,
14	    *::before,
15	    *::after {
16	      box-sizing: border-box;
17	      margin: 0;
18	      padding: 0;
19	    }
20	    :root {
21	      color-scheme: light dark;
22	      --bg: #fff;
23	      --text: #374151;
24	      --fg: #2563eb;
25	      --shadow: rgba(0, 0, 0, 0.1);
26	      --kbd-bg: rgba(0, 0, 0, 0.1);
27	      --drop: drop-shadow(0 4px 12px var(--shadow));
28	    }
29	    [data-color="red"] { --fg: #dc2626; }
30	    [data-color="green"] { --fg: #16a34a; }
31	    [data-color="amber"] { --fg: #d97706; }
32	    [data-color="violet"] { --fg: #7c3aed; }
33	    [data-color="cyan"] { --fg: #0891b2; }
34	    @media (prefers-color-scheme: dark) {
35	      :root {
36	        --bg: #111;
37	        --text: #d1d5db;
38	        --fg: #93c5fd;
39	        --shadow: rgba(0, 0, 0, 0.6);
40	        --kbd-bg: rgba(255, 255, 255, 0.15);
41	      }
42	      [data-color="red"] { --fg: #fca5a5; }
43	      [data-color="green"] { --fg: #86efac; }
44	      [data-color="amber"] { --fg: #fcd34d; }
45	      [data-color="violet"] { --fg: #c4b5fd; }
46	      [data-color="cyan"] { --fg: #67e8f9; }
47	    }
48	    @media (prefers-contrast: more) {
49	      :root {
50	        --shadow: rgba(0, 0, 0, 0.9);
51	        --drop: drop-shadow(0 2px 8px var(--shadow));
52	      }
53	      .circle svg {
54	        opacity: 1;
55	      }
56	    }
57	    @media (forced-colors: active) {
58	      svg circle {
59	        stroke: CanvasText;
60	        stroke-width: 2;
61	      }
62	    }
63	    body {
64	      min-height: 100vh;
65	      min-height: 100dvh;
66	      display: grid;
67	      place-items: center;
68	      padding: 1rem;
69	      background: var(--bg);
70	      color: var(--text);
71	      font-family: system-ui, -apple-system, sans-serif;
72	    }
73	    main {
74	      width: 100%;
75	      display: flex;
76	      flex-direction: column;
77	      align-items: center;
78	      text-align: center;
79	    }
80	    .circle {
81	      display: block;
82	      width: min(360px, 100%, 60vh);
83	      aspect-ratio: 1;
84	      border: 0;
85	      border-radius: 50%;
86	      background: none;
87	      color: var(--fg);
88	      cursor: pointer;
89	      touch-action: manipulation;
90	      -webkit-tap-highlight-color: transparent;
91	      /* Shift+click and double-click would otherwise select the text below */
92	      -webkit-user-select: none;
93	      user-select: none;
94	      transition: color 0.4s ease;
95	      min-height: 48px;
96	      min-width: 48px;
97	    }
98	    .no-transition,
99	    .no-transition svg {
100	      transition: none !important;
101	    }
102	    .circle:focus-visible {
103	      outline: 3px solid currentColor;
104	      /* Must clear the scaled-up circle (up to 9px) or the ring merges with it */
105	      outline-offset: 12px;
106	    }
107	    svg {
108	      display: block;
109	      width: 100%;
110	      height: 100%;
111	      overflow: visible;
112	      opacity: 0.85;
113	      filter: var(--drop);
114	      transition: opacity 0.3s ease;
115	    }
116	    .circle:active svg,
117	    .circle:focus-visible svg {
118	      opacity: 1;
119	    }
120	    @keyframes pulse {
121	      0% {
122	        filter: var(--drop) drop-shadow(0 0 16px currentColor);
123	      }
124	      100% {
125	        filter: var(--drop) drop-shadow(0 0 0 transparent);
126	      }
127	    }
128	    @media (hover: hover) {
129	      .circle:hover svg {
130	        opacity: 1;
131	      }
132	    }
133	    @media (prefers-reduced-motion: no-preference) {
134	      svg {
135	        transition:
136	          transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1),
137	          opacity 0.3s ease;
138	      }
139	      .circle:focus-visible svg {
140	        transform: scale(1.05);
141	      }
142	      .circle:active svg {
143	        transform: scale(0.97);
144	      }
145	      .circle.color-changed svg {
146	        animation: pulse 0.5s ease-out;
147	      }
148	    }
149	    @media (hover: hover) and (prefers-reduced-motion: no-preference) {
150	      .circle:hover:not(:active) svg {
151	        transform: scale(1.05);
152	      }
153	    }
154	    .visually-hidden {
155	      position: absolute;
156	      width: 1px;
157	      height: 1px;
158	      overflow: hidden;
159	      clip-path: inset(50%);
160	      white-space: nowrap;
161	    }
162	    .status {
163	      margin-top: 2rem;
164	      font-weight: 600;
165	    }
166	    .hint {
167	      margin-top: 0.25rem;
168	      font-size: 0.875rem;
169	      line-height: 1.75;
170	    }
171	    .help-button {
172	      margin-left: 0.5rem;
173	      display: inline-block;
174	      width: 1.5rem;
175	      height: 1.5rem;
176	      border-radius: 50%;
177	      background: var(--kbd-bg);
178	      border: 1px solid var(--text);
179	      color: var(--text);
180	      cursor: pointer;
181	      font: inherit;
182	      font-size: 0.75rem;
183	      font-weight: bold;
184	      line-height: 1;
185	      text-align: center;
186	      vertical-align: middle;
187	      touch-action: manipulation;
188	      transition: background-color 0.2s ease, color 0.2s ease;
189	    }
190	    .help-button:focus-visible {
191	      outline: 2px solid currentColor;
192	      outline-offset: 2px;
193	    }
194	    @media (hover: hover) {
195	      /* Not currentColor: it would resolve to the hover color and hide the "?" */
196	      .help-button:hover {
197	        background: var(--text);
198	        color: var(--bg);
199	      }
200	    }
201	    .keys {
202	      display: none;
203	    }
204	    .keys.visible {
205	      display: inline;
206	    }
207	    @media (hover: none) and (pointer: coarse) {
208	      .hint .keys {
209	        display: none !important;
210	      }
211	      .help-button {
212	        display: none;
213	      }
214	    }
215	    kbd {
216	      display: inline-block;
217	      padding: 0.125rem 0.375rem;
218	      background: var(--kbd-bg);
219	      border: 1px solid transparent;
220	      border-radius: 0.25rem;
221	      font-family: monospace;
222	      font-size: 0.75em;
223	      line-height: 1.2;
224	    }
225	  </style>
226	</head>
227	<body>
228	  <main>
229	    <h1 class="visually-hidden">Animated Circle</h1>
230	    <button type="button" class="circle no-transition" aria-label="Change circle color" aria-describedby="status hint">
231	      <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg">
232	        <circle cx="50" cy="50" r="50" fill="currentColor"/>
233	      </svg>
234	    </button>
235	    <p class="status" id="status" role="status">Blue</p>
236	    <p class="hint"><span id="hint"><span class="verb">Click</span> to cycle • <span class="double-verb">Double-click</span> to reset<span class="keys" id="keys"> • <kbd>Shift</kbd>+click reverse • <kbd>↑↓←→</kbd> navigate • <kbd>Home</kbd>/<kbd>End</kbd> jump</span></span> <button type="button" class="help-button" aria-label="Keyboard shortcuts" aria-expanded="false" aria-controls="keys"><span aria-hidden="true">?</span></button></p>
237	  </main>
238	  <script>
239	    const button = document.querySelector('.circle');
240	    const status = document.querySelector('.status');
241	    const helpButton = document.querySelector('.help-button');
242	    const keyHint = document.querySelector('.keys');
243	    const colors = ['blue', 'red', 'green', 'amber', 'violet', 'cyan'];
244	    const storageKey = 'circle-color';
245	    const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
246	
247	    // Safely retrieve saved color from localStorage, returning null if unavailable
248	    function loadColor() {
249	      try {
250	        return localStorage.getItem(storageKey);
251	      } catch {
252	        return null;
253	      }
254	    }
255	
256	    // Safely save color to localStorage, silently failing if unavailable
257	    function saveColor(color) {
258	      try {
259	        localStorage.setItem(storageKey, color);
260	      } catch {}
261	    }
262	
263	    const savedColor = loadColor();
264	    let index = colors.includes(savedColor) ? colors.indexOf(savedColor) : 0;
265	
266	    // Apply current color to button and update status display
267	    function applyColor() {
268	      const color = colors[index];
269	      if (color === 'blue') {
270	        delete button.dataset.color;
271	      } else {
272	        button.dataset.color = color;
273	      }
274	      // The status live region announces the change; the button's label stays
275	      // fixed so screen readers don't read the color twice
276	      status.textContent = color[0].toUpperCase() + color.slice(1);
277	    }
278	
279	    // Switch to the color at the given index, persist it and trigger pulse animation
280	    function setIndex(next, { haptic = false } = {}) {
281	      // Home/End at the boundary shouldn't pulse or rewrite storage
282	      if (next === index) return;
283	      index = next;
284	      applyColor();
285	      saveColor(colors[index]);
286	
287	      // Haptic feedback for supported devices
288	      if (haptic && navigator.vibrate) navigator.vibrate(50);
289	
290	      // With reduced motion no animation runs, so animationend would never clear the class
291	      if (reducedMotion.matches) return;
292	      button.classList.remove('color-changed');
293	      void button.offsetWidth;
294	      button.classList.add('color-changed');
295	    }
296	
297	    // Cycle color by step amount
298	    function changeColor(step) {
299	      setIndex((index + step + colors.length) % colors.length, { haptic: true });
300	    }
301	
302	    applyColor();
303	    // Double rAF ensures paint completes before enabling animations
304	    requestAnimationFrame(() => requestAnimationFrame(() => {
305	      button.classList.remove('no-transition');
306	    }));
307	
308	    // Update instructions to show "Tap" on touch devices or "Click" on hover-capable devices
309	    const hoverQuery = matchMedia('(hover: none)');
310	    const verbSpan = document.querySelector('.hint .verb');
311	    const doubleVerbSpan = document.querySelector('.hint .double-verb');
312	    function updateVerb() {
313	      verbSpan.textContent = hoverQuery.matches ? 'Tap' : 'Click';
314	      doubleVerbSpan.textContent = hoverQuery.matches ? 'Double-tap' : 'Double-click';
315	    }
316	    updateVerb();
317	    hoverQuery.addEventListener('change', updateVerb);
318	
319	    // Space and Enter activate through the native click, but keyboard-synthesized
320	    // clicks don't reliably carry shiftKey, so remember it from the key events
321	    let shiftHeld = false;
322	    const isActivationKey = (event) => event.key === 'Enter' || event.key === ' ';
323	    // Space clicks on keyup; Enter already clicked on keydown, so updating
324	    // shiftHeld on Enter's keyup would leak into the next mouse click
325	    button.addEventListener('keyup', (event) => {
326	      if (event.key === ' ') shiftHeld = event.shiftKey;
327	    });
328	    button.addEventListener('blur', () => {
329	      shiftHeld = false;
330	    });
331	
332	    const keySteps = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
333	    button.addEventListener('keydown', (event) => {
334	      if (isActivationKey(event)) {
335	        // Holding Enter would otherwise fire a click on every repeat; no click
336	        // follows to reset shiftHeld, so setting it here would leak into the
337	        // next mouse click
338	        if (event.repeat) {
339	          if (event.key === 'Enter') event.preventDefault();
340	          return;
341	        }
342	        shiftHeld = event.shiftKey;
343	        return;
344	      }
345	      if (event.altKey || event.ctrlKey || event.metaKey) return;
346	      if (event.key in keySteps) {
347	        event.preventDefault();
348	        changeColor(keySteps[event.key]);
349	      } else if (event.key === 'Home') {
350	        event.preventDefault();
351	        setIndex(0, { haptic: true });
352	      } else if (event.key === 'End') {
353	        event.preventDefault();
354	        setIndex(colors.length - 1, { haptic: true });
355	      }
356	    });
357	    button.addEventListener('click', (event) => {
358	      // event.detail is 2+ for clicks that are part of a dblclick; skip them
359	      // so double-click resets cleanly instead of cycling twice then resetting
360	      if (event.detail > 1) return;
361	      changeColor(event.shiftKey || shiftHeld ? -1 : 1);
362	      shiftHeld = false;
363	    });
364	    button.addEventListener('animationend', () => {
365	      button.classList.remove('color-changed');
366	    });
367	    button.addEventListener('dblclick', (event) => {
368	      event.preventDefault();
369	      setIndex(0);
370	    });
371	    helpButton.addEventListener('click', () => {
372	      const expanded = keyHint.classList.toggle('visible');
373	      helpButton.setAttribute('aria-expanded', expanded);
374	    });
375	    // Show keyboard shortcuts by default on desktop
376	    if (!hoverQuery.matches) {
377	      keyHint.classList.add('visible');
378	      helpButton.setAttribute('aria-expanded', 'true');
379	    }
380	    // Sync color across tabs when storage changes
381	    addEventListener('storage', (event) => {
382	      // key is null when another tab calls localStorage.clear()
383	      if (event.key !== storageKey && event.key !== null) return;
384	      const newIndex = colors.indexOf(event.newValue);
385	      index = newIndex === -1 ? 0 : newIndex;
386	      applyColor();
387	    });
388	  </script>
389	</body>
390	</html>
